import{_ as a,o as t,c as n,a5 as i}from"./chunks/framework.DvE3tBec.js";const f=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"documentation/1.0/developers/index.md","filePath":"documentation/1.0/developers/README.md","lastUpdated":1791387718000}'),o={name:"documentation/1.0/developers/index.md"};function r(d,e,s,l,c,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>The openEO API defines a <a href="./api/reference.html">HTTP API</a> that lets cloud back-ends with large Earth observation datasets communicate with front end analysis applications in an interoperable way.</p><p>As an overview, the openEO API specifies how to</p><ul><li>discover which Earth observation data and processes are available at cloud back-ends,</li><li>execute (chained) processes on back-ends,</li><li>run <a href="./../udfs.html">user-defined functions</a> (UDFs) on back-ends where UDFs can be exposed to the data in different ways,</li><li>download (intermediate) results, and</li><li>manage user content including billing.</li></ul><p>The API is defined as an <a href="https://github.com/OAI/OpenAPI-Specification/blob/master/versions/3.0.1.md" target="_blank" rel="noreferrer">OpenAPI 3.0</a> YAML file.</p><p>The API and processes are grouped into <a href="./profiles/">compliance profiles</a>.</p><h2 id="additional-information" tabindex="-1">Additional information <a class="header-anchor" href="#additional-information" aria-label="Permalink to &quot;Additional information&quot;">​</a></h2><ul><li><a href="/documentation/code-of-conduct.html">Code of Conduct</a></li><li><a href="/documentation/software-guidelines.html">Software Development Guidelines</a></li></ul>',8)])])}const h=a(o,[["render",r]]);export{f as __pageData,h as default};
